__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"avisDocument",{enumerable:!0,get:function(){return s}});var n=r(d[0]),t=r(d[1]);const s=(0,n.publishedDocument)({id:"avis",slug:"avis",title:"Politique des avis clients",shortTitle:"Avis clients",sections:[{heading:"1. Objet",paragraphs:[`La pr\xe9sente politique explique comment ${t.LEGAL_TRADE_NAME}, service \xe9dit\xe9 par ${t.LEGAL_OPERATOR_NAME}, collecte, contr\xf4le, publie, classe, mod\xe8re et conserve les avis d\xe9pos\xe9s par les Clients.`,"Elle vise \xe0 permettre aux utilisateurs de comprendre l'origine des avis publi\xe9s, les contr\xf4les effectu\xe9s par Croki et les r\xe8gles appliqu\xe9es lorsqu'un avis est refus\xe9, masqu\xe9 ou signal\xe9.","Cette politique compl\xe8te notamment les CGU Client, la Politique de confidentialit\xe9 et les r\xe8gles g\xe9n\xe9rales de fonctionnement de la marketplace Croki."]},{heading:"2. Qu\u2019est-ce qu\u2019un avis Croki ?",paragraphs:["Un avis Croki est l'expression de l'opinion d'un Client concernant son exp\xe9rience aupr\xe8s d'un \xc9tablissement \xe0 la suite d'une Commande effectu\xe9e au moyen de Croki.","L'avis comprend une note et peut comprendre un commentaire lorsque le Client souhaite ajouter un texte.","L'avis est rattach\xe9 \xe0 l'\xc9tablissement concern\xe9 par la Commande.","Les avis Croki ne sont pas des avis d'experts et ne constituent pas une certification de la qualit\xe9 de l'\xc9tablissement ou de ses produits par FOODTECH SOLUTIONS."]},{heading:"3. Qui peut publier un avis ?",paragraphs:["Seul un Client disposant d'un compte Croki et associ\xe9 \xe0 la Commande concern\xe9e peut publier un avis.","La Commande doit avoir atteint l'\xe9tat correspondant \xe0 un retrait confirm\xe9 avant que l'avis puisse \xeatre d\xe9pos\xe9.","Une Commande annul\xe9e, refus\xe9e, expir\xe9e, non accept\xe9e ou non retir\xe9e ne permet pas de d\xe9poser un avis au moyen du m\xe9canisme normal de Croki.","Cette r\xe8gle d'\xe9ligibilit\xe9 est contr\xf4l\xe9e par le Service et ne repose pas uniquement sur une d\xe9claration du Client."]},{heading:"4. Un seul avis par Commande",paragraphs:["Une m\xeame Commande ne peut donner lieu qu'\xe0 un seul avis Client.","Croki applique cette r\xe8gle au niveau du Service afin d'emp\xeacher qu'un m\xeame Client multiplie les avis \xe0 partir d'une seule Commande.","Un Client ayant effectu\xe9 plusieurs Commandes distinctes aupr\xe8s d'un m\xeame \xc9tablissement peut \xeatre \xe9ligible \xe0 d\xe9poser un avis pour chacune de ces exp\xe9riences lorsque les conditions pr\xe9vues par Croki sont remplies."]},{heading:"5. Contr\xf4le de l\u2019exp\xe9rience de consommation",paragraphs:["Croki exerce un contr\xf4le technique avant d'autoriser le d\xe9p\xf4t d'un avis.","Croki v\xe9rifie notamment que le compte Client est associ\xe9 \xe0 la Commande concern\xe9e, que cette Commande existe dans Croki et que son retrait a \xe9t\xe9 confirm\xe9.","Ce m\xe9canisme permet \xe0 Croki d'\xe9tablir que l'auteur de l'avis est associ\xe9 \xe0 une Commande effectivement r\xe9alis\xe9e au moyen de Croki aupr\xe8s de l'\xc9tablissement concern\xe9.","Croki ne se contente donc pas d'une simple d\xe9claration de l'utilisateur affirmant avoir command\xe9 aupr\xe8s de l'\xc9tablissement."]},{heading:"6. Signification de la mention li\xe9e \xe0 une Commande Croki",paragraphs:["Croki peut indiquer \xe0 proximit\xe9 d'un avis que celui-ci est li\xe9 \xe0 une Commande Croki dont le retrait a \xe9t\xe9 confirm\xe9.","Cette mention signifie uniquement que Croki a v\xe9rifi\xe9 techniquement l'existence de la Commande, son rattachement au compte Client et son \xe9tat de retrait conform\xe9ment aux r\xe8gles du Service.","Elle ne signifie pas que FOODTECH SOLUTIONS a v\xe9rifi\xe9 mat\xe9riellement chaque affirmation contenue dans le commentaire.","Elle ne constitue pas une certification d\xe9livr\xe9e par l'\xc9tat, une autorit\xe9 publique ou un organisme ind\xe9pendant."]},{heading:"7. Ce que Croki ne garantit pas",paragraphs:["Le contr\xf4le technique de Croki ne permet pas de garantir l'exactitude objective de chacune des opinions ou affirmations exprim\xe9es dans un commentaire.","Une appr\xe9ciation relative au go\xfbt, \xe0 l'accueil, \xe0 l'attente, \xe0 la qualit\xe9 per\xe7ue ou \xe0 l'exp\xe9rience du Client demeure notamment subjective.","Croki ne pr\xe9sente donc pas les commentaires comme des faits certifi\xe9s par FOODTECH SOLUTIONS.","Croki prend n\xe9anmoins des mesures destin\xe9es \xe0 limiter les faux avis, les manipulations et les contenus contraires \xe0 la pr\xe9sente politique."]},{heading:"8. Contenu d\u2019un avis",paragraphs:["L'avis comprend une note attribu\xe9e par le Client.","Le Client peut \xe9galement ajouter un commentaire lorsque cette fonctionnalit\xe9 est propos\xe9e.","L'avis est associ\xe9 \xe0 l'\xc9tablissement concern\xe9 ainsi qu'aux informations techniques n\xe9cessaires \xe0 son contr\xf4le, \xe0 son classement et \xe0 sa mod\xe9ration.","La date de publication de l'avis est affich\xe9e avec celui-ci.","Croki affiche \xe9galement la date correspondant \xe0 l'exp\xe9rience de consommation prise en compte par le Service."]},{heading:"9. Date de l\u2019exp\xe9rience de consommation",paragraphs:["Pour les avis Croki, la date de l'exp\xe9rience de consommation affich\xe9e correspond \xe0 la date de retrait confirm\xe9 de la Commande concern\xe9e.","Cette date constitue le rep\xe8re objectif dont dispose Croki pour rattacher l'avis \xe0 l'exp\xe9rience r\xe9alis\xe9e au moyen du Service.","Elle ne pr\xe9tend pas d\xe9terminer l'heure exacte \xe0 laquelle le Client a consomm\xe9 les produits apr\xe8s leur retrait."]},{heading:"10. Date de publication",paragraphs:["La date de publication de chaque avis est affich\xe9e \xe0 proximit\xe9 de l'avis.","Lorsqu'un avis est publi\xe9 imm\xe9diatement apr\xe8s son enregistrement et les contr\xf4les techniques n\xe9cessaires, sa date de publication correspond \xe0 cette publication effective.","Croki ne modifie pas artificiellement la date de publication afin d'am\xe9liorer ou d\xe9grader la visibilit\xe9 d'un avis."]},{heading:"11. D\xe9lai maximal de publication",paragraphs:["Lorsqu'un avis satisfait aux conditions de d\xe9p\xf4t et ne n\xe9cessite pas de v\xe9rification compl\xe9mentaire, sa publication est normalement effectu\xe9e imm\xe9diatement apr\xe8s son enregistrement technique.","Croki fixe \xe0 sept jours calendaires le d\xe9lai maximal de publication d'un avis valablement d\xe9pos\xe9 lorsque son traitement n\xe9cessite une v\xe9rification ou une intervention suppl\xe9mentaire.","Lorsqu'un avis est refus\xe9 plut\xf4t que publi\xe9, son auteur est inform\xe9 du motif de ce refus."]},{heading:"12. Classement des avis",paragraphs:["Croki permet de comprendre l'ordre dans lequel les avis sont pr\xe9sent\xe9s.","Le classement chronologique fait partie des crit\xe8res de classement des avis Croki.","Dans l'affichage chronologique, les avis sont class\xe9s selon leur date de publication, les plus r\xe9cents \xe9tant pr\xe9sent\xe9s avant les plus anciens.","Si Croki propose ult\xe9rieurement d'autres tris, par exemple par note, leur fonctionnement sera identifi\xe9 clairement dans l'interface et la pr\xe9sente politique sera mise \xe0 jour."]},{heading:"13. Absence de classement payant des avis",paragraphs:["Aucun Client ni Professionnel ne peut payer Croki pour obtenir une meilleure position d'un avis dans la liste.","La commission vers\xe9e par un Professionnel \xe0 Croki n'influence pas l'ordre de ses avis.","Le caract\xe8re positif ou n\xe9gatif d'un avis ne lui conf\xe8re pas, par lui-m\xeame, une priorit\xe9 de publication ou de classement.","Croki ne retarde pas volontairement les avis n\xe9gatifs afin de favoriser artificiellement l'image d'un Professionnel."]},{heading:"14. Aucune contrepartie pour d\xe9poser un avis",paragraphs:["Croki ne fournit actuellement aucune contrepartie au Client en \xe9change du d\xe9p\xf4t d'un avis.","Le Client ne re\xe7oit notamment aucune r\xe9duction, remboursement, cr\xe9dit, cadeau, avantage financier ou am\xe9lioration de son compte Croki en contrepartie du d\xe9p\xf4t d'un avis.","La publication d'un avis positif n'est jamais une condition pour obtenir un avantage de Croki.","Si Croki organise ult\xe9rieurement une op\xe9ration comportant une contrepartie en \xe9change du d\xe9p\xf4t d'un avis, cette contrepartie sera clairement indiqu\xe9e et la pr\xe9sente politique sera mise \xe0 jour avant l'op\xe9ration."]},{heading:"15. Avis positifs et n\xe9gatifs",paragraphs:["Les avis positifs et n\xe9gatifs sont soumis aux m\xeames r\xe8gles de contr\xf4le et de mod\xe9ration.","Un avis ne peut pas \xeatre refus\xe9, masqu\xe9 ou supprim\xe9 du seul fait qu'il exprime une opinion n\xe9gative sur l'\xc9tablissement ou l'exp\xe9rience du Client.","Un commentaire critique peut rester publi\xe9 d\xe8s lors qu'il respecte la loi et les r\xe8gles de contenu pr\xe9vues par la pr\xe9sente politique.","Le Professionnel ne dispose pas d'un droit de suppression d'un avis simplement parce qu'il le juge d\xe9favorable."]},{heading:"16. Modification d\u2019un avis par le Client",paragraphs:["Dans le fonctionnement actuel de Croki, un avis publi\xe9 ne peut pas \xeatre modifi\xe9 par son auteur.","Le Client doit donc v\xe9rifier sa note et son commentaire avant de confirmer leur publication.","Aucune modification ult\xe9rieure du texte ou de la note n'est propos\xe9e dans le fonctionnement actuel.","Si une fonctionnalit\xe9 de modification est introduite ult\xe9rieurement, Croki indiquera les modalit\xe9s de modification et affichera les informations relatives aux mises \xe0 jour conform\xe9ment aux r\xe8gles applicables."]},{heading:"17. Suppression demand\xe9e par l\u2019auteur",paragraphs:["Le fait qu'un avis ne soit pas modifiable ne prive pas son auteur de la possibilit\xe9 de contacter Croki lorsqu'il estime qu'un contenu doit \xeatre retir\xe9 ou lorsqu'il souhaite exercer un droit applicable \xe0 ses donn\xe9es personnelles.","Une demande est examin\xe9e au regard de la nature de l'avis, des droits de l'auteur, des droits des tiers, des obligations de conservation et de la base juridique permettant \xe9ventuellement \xe0 Croki de maintenir certaines informations.","Les droits relatifs aux donn\xe9es personnelles sont d\xe9taill\xe9s dans la Politique de confidentialit\xe9."]},{heading:"18. R\xe9ponse du Professionnel",paragraphs:["Le Professionnel concern\xe9 peut publier une r\xe9ponse \xe0 un avis lorsque la fonctionnalit\xe9 correspondante est disponible.","Dans le fonctionnement actuel de Croki, une seule r\xe9ponse du Professionnel est associ\xe9e \xe0 un avis.","La r\xe9ponse est affich\xe9e s\xe9par\xe9ment de l'avis du Client et ne modifie ni la note ni le commentaire du Client.","La r\xe9ponse du Professionnel est elle-m\xeame soumise aux r\xe8gles de contenu et de mod\xe9ration applicables sur Croki."]},{heading:"19. Contr\xf4le et mod\xe9ration",paragraphs:["Croki exerce un contr\xf4le technique au moment du d\xe9p\xf4t de l'avis et peut \xe9galement exercer une mod\xe9ration apr\xe8s sa publication.","Le contr\xf4le technique v\xe9rifie notamment l'\xe9ligibilit\xe9 du Client, l'existence et l'\xe9tat de la Commande ainsi que l'absence d'un autre avis d\xe9j\xe0 associ\xe9 \xe0 la m\xeame Commande.","La mod\xe9ration peut \xeatre d\xe9clench\xe9e \xe0 la suite d'un signalement, d'un contr\xf4le de s\xe9curit\xe9, d'une d\xe9tection d'abus ou d'une intervention de FOODTECH SOLUTIONS.","Croki ne r\xe9\xe9crit pas un commentaire Client afin de le rendre plus favorable ou plus d\xe9favorable au Professionnel."]},{heading:"20. Motifs pouvant justifier un refus ou un retrait",paragraphs:["Un avis peut \xeatre refus\xe9, masqu\xe9 ou retir\xe9 lorsqu'un motif l\xe9gitime le justifie."],bullets:["La Commande requise pour d\xe9poser l'avis n'existe pas, n'appartient pas au Client ou ne remplit pas les conditions d'\xe9ligibilit\xe9.","Un avis a d\xe9j\xe0 \xe9t\xe9 publi\xe9 pour la m\xeame Commande.","Le contenu est manifestement sans rapport avec l'\xc9tablissement ou l'exp\xe9rience concern\xe9e.","Le contenu comporte des propos manifestement illicites.","Le contenu contient des menaces, du harc\xe8lement ou des propos haineux ou discriminatoires.","Le contenu porte ill\xe9galement atteinte \xe0 la r\xe9putation, \xe0 la vie priv\xe9e ou aux droits d'un tiers.","Le contenu divulgue sans n\xe9cessit\xe9 des donn\xe9es personnelles, coordonn\xe9es priv\xe9es ou informations confidentielles appartenant \xe0 un tiers.","Le contenu constitue du spam, une publicit\xe9, une sollicitation commerciale ou contient des liens manifestement abusifs.","L'avis est faux, frauduleux ou fait partie d'une tentative de manipulation artificielle des notes ou du classement.","L'auteur usurpe l'identit\xe9 d'un tiers ou fournit d\xe9lib\xe9r\xe9ment de fausses informations afin de contourner les r\xe8gles de Croki.","Le contenu vise \xe0 contourner la s\xe9curit\xe9 ou \xe0 exploiter abusivement le Service.","Une obligation l\xe9gale, une d\xe9cision d'une autorit\xe9 comp\xe9tente ou la protection des droits d'un tiers impose son retrait."]},{heading:"21. Ce qui ne constitue pas un motif de refus",paragraphs:["Le seul fait qu'un avis soit n\xe9gatif ne constitue pas un motif de refus.","Le seul fait qu'une note soit faible ne constitue pas un motif de refus.","Le fait qu'un Professionnel conteste l'opinion subjective exprim\xe9e par un Client ne suffit pas automatiquement \xe0 justifier son retrait.","Le fait qu'un avis puisse avoir un effet d\xe9favorable sur la note moyenne ou l'image commerciale d'un \xc9tablissement ne constitue pas, \xe0 lui seul, un motif de suppression."]},{heading:"22. Information de l\u2019auteur en cas de refus",paragraphs:["Lorsqu'un avis n'est pas publi\xe9, Croki informe son auteur du motif justifiant le refus par un moyen appropri\xe9.","Lorsque Croki retire ou masque ult\xe9rieurement un avis d\xe9j\xe0 publi\xe9 et que l'auteur peut \xeatre identifi\xe9 et contact\xe9, Croki lui fournit l'information requise concernant la d\xe9cision dans les conditions applicables.","Le motif communiqu\xe9 doit permettre \xe0 l'auteur de comprendre la r\xe8gle ayant conduit \xe0 la d\xe9cision, sous r\xe9serve des informations qui ne peuvent pas \xeatre divulgu\xe9es pour des raisons l\xe9gales, de s\xe9curit\xe9 ou de protection de tiers."]},{heading:"23. Doute du Professionnel sur l\u2019authenticit\xe9",paragraphs:["Le Professionnel faisant l'objet d'un avis peut signaler gratuitement \xe0 Croki un doute sur l'authenticit\xe9 de cet avis.","Le signalement doit \xeatre motiv\xe9.","Le Professionnel doit expliquer les \xe9l\xe9ments lui permettant de penser que l'avis pourrait ne pas correspondre \xe0 une exp\xe9rience r\xe9elle ou pourrait avoir fait l'objet d'une manipulation.","Aucun paiement n'est demand\xe9 au Professionnel pour effectuer ce signalement.","Le seul d\xe9p\xf4t d'un signalement ne provoque pas automatiquement la suppression de l'avis."]},{heading:"24. Examen d\u2019un signalement d\u2019authenticit\xe9",paragraphs:["Croki examine le signalement au regard des informations disponibles dans le Service.","Croki peut notamment v\xe9rifier l'existence de la Commande, son rattachement au compte Client, son \xe9tat de retrait, les \xe9l\xe9ments techniques associ\xe9s \xe0 l'avis et les informations communiqu\xe9es dans le signalement.","Croki peut demander des informations compl\xe9mentaires lorsque celles-ci sont raisonnablement n\xe9cessaires \xe0 l'examen du doute.","L'avis peut \xeatre maintenu, masqu\xe9 ou retir\xe9 selon le r\xe9sultat du contr\xf4le et les r\xe8gles applicables."]},{heading:"25. Possibilit\xe9 de contacter l\u2019auteur",paragraphs:["Lorsque cela est n\xe9cessaire pour contr\xf4ler un avis, traiter un signalement ou respecter une obligation l\xe9gale, Croki peut contacter l'auteur de l'avis au moyen des coordonn\xe9es ou canaux associ\xe9s \xe0 son compte et encore disponibles.","Croki ne communique pas au Professionnel l'adresse \xe9lectronique priv\xe9e ou les coordonn\xe9es personnelles du Client uniquement parce que le Professionnel souhaite contester un avis.","Les traitements de donn\xe9es r\xe9alis\xe9s dans ce cadre sont d\xe9crits dans la Politique de confidentialit\xe9."]},{heading:"26. Faux avis et manipulations",paragraphs:["La cr\xe9ation, l'achat, la vente ou l'organisation de faux avis est interdite sur Croki.","Il est notamment interdit de cr\xe9er artificiellement des Commandes ou comptes dans le seul but de manipuler les notes, d'inciter \xe0 publier un faux avis, de r\xe9diger un avis sous l'identit\xe9 d'un tiers ou d'organiser une campagne destin\xe9e \xe0 augmenter ou diminuer artificiellement la r\xe9putation d'un \xc9tablissement.","Il est \xe9galement interdit \xe0 un Professionnel de demander \xe0 Croki de modifier le contenu d'avis r\xe9els afin de promouvoir artificiellement ses produits ou son \xc9tablissement.","Croki peut prendre des mesures contre les comptes ou \xe9tablissements impliqu\xe9s dans une manipulation av\xe9r\xe9e, conform\xe9ment aux CGU et Conditions Pro."]},{heading:"27. Signalement d\u2019un contenu potentiellement illicite",paragraphs:["Une personne peut utiliser le m\xe9canisme de signalement propos\xe9 par Croki lorsqu'elle estime qu'un avis ou une r\xe9ponse comporte un contenu potentiellement illicite ou contraire aux r\xe8gles du Service.","Le signalement doit identifier suffisamment le contenu concern\xe9 et expliquer le motif de la demande.","Le m\xe9canisme g\xe9n\xe9ral de signalement est distinct du m\xe9canisme sp\xe9cifique permettant au Professionnel de signaler gratuitement un doute motiv\xe9 sur l'authenticit\xe9 d'un avis.","Croki examine les signalements conform\xe9ment aux r\xe8gles de mod\xe9ration et aux obligations applicables."]},{heading:"28. Protection contre les signalements abusifs",paragraphs:["Les m\xe9canismes de signalement doivent \xeatre utilis\xe9s de bonne foi.","Le d\xe9p\xf4t r\xe9p\xe9t\xe9 de signalements manifestement infond\xe9s dans le but de faire dispara\xeetre des critiques l\xe9gitimes ou de harceler un utilisateur peut constituer un usage abusif du Service.","Croki peut prendre des mesures proportionn\xe9es contre les utilisations abusives de ses m\xe9canismes de signalement conform\xe9ment aux CGU et Conditions Pro."]},{heading:"29. Calcul de la note moyenne",paragraphs:["La note moyenne affich\xe9e pour un \xc9tablissement est calcul\xe9e \xe0 partir des avis publi\xe9s pris en compte par Croki.","Un avis qui n'est plus publi\xe9 \xe0 la suite d'une d\xe9cision de mod\xe9ration ne doit pas continuer \xe0 influencer publiquement la note moyenne lorsqu'il est exclu des avis affich\xe9s selon le fonctionnement du Service.","Croki ne modifie pas manuellement la note d'un avis afin d'augmenter ou de diminuer artificiellement la moyenne d'un \xc9tablissement.","La r\xe9mun\xe9ration vers\xe9e \xe0 Croki par un Professionnel n'a aucune influence directe sur la note moyenne."]},{heading:"30. D\xe9lai maximal de conservation publique",paragraphs:["Croki fixe \xe0 cinq ans \xe0 compter de leur publication la dur\xe9e maximale normale d'affichage public des avis.","Un avis peut \xeatre retir\xe9 avant cette \xe9ch\xe9ance lorsqu'un motif de mod\xe9ration, une demande juridiquement fond\xe9e, une obligation l\xe9gale ou une autre raison l\xe9gitime le justifie.","\xc0 l'expiration de la dur\xe9e maximale d'affichage public, l'avis n'est plus destin\xe9 \xe0 rester publiquement accessible.","Certaines informations strictement n\xe9cessaires peuvent toutefois \xeatre conserv\xe9es s\xe9par\xe9ment pendant une dur\xe9e suppl\xe9mentaire lorsqu'une obligation l\xe9gale, la pr\xe9vention de la fraude, la preuve d'une op\xe9ration, la gestion d'un litige ou la d\xe9fense de droits le justifie.","Les r\xe8gles relatives aux donn\xe9es personnelles et \xe0 leur conservation sont d\xe9taill\xe9es dans la Politique de confidentialit\xe9."]},{heading:"31. Suppression d\u2019un compte Client",paragraphs:["La suppression du compte Client n'entra\xeene pas n\xe9cessairement la disparition imm\xe9diate de tout avis d\xe9j\xe0 publi\xe9.","Lorsqu'un avis peut l\xe9gitimement rester publi\xe9, les donn\xe9es permettant d'identifier directement son auteur sont supprim\xe9es ou anonymis\xe9es lorsqu'elles ne sont plus n\xe9cessaires.","Les informations techniques n\xe9cessaires \xe0 la preuve du contr\xf4le de l'avis, \xe0 la pr\xe9vention de la fraude ou au traitement d'un litige peuvent \xeatre conserv\xe9es pendant la dur\xe9e l\xe9galement justifi\xe9e.","La Politique de confidentialit\xe9 d\xe9crit plus pr\xe9cis\xe9ment les cons\xe9quences de la suppression d'un compte sur les donn\xe9es personnelles."]},{heading:"32. Fermeture ou d\xe9r\xe9f\xe9rencement d\u2019un \xc9tablissement",paragraphs:["La fermeture, suspension ou fin de r\xe9f\xe9rencement d'un \xc9tablissement n'entra\xeene pas n\xe9cessairement l'effacement imm\xe9diat de tous les avis historiquement publi\xe9s \xe0 son sujet.","Croki peut conserver certains avis pendant la dur\xe9e pr\xe9vue par la pr\xe9sente politique lorsque cela reste pertinent, licite et n\xe9cessaire \xe0 la transparence ou \xe0 la preuve des exp\xe9riences pass\xe9es.","Un \xc9tablissement qui n'est plus disponible \xe0 la Commande doit toutefois \xeatre identifi\xe9 comme tel lorsque son ancienne fiche ou ses avis restent accessibles."]},{heading:"33. Donn\xe9es personnelles",paragraphs:["La collecte et le traitement des donn\xe9es n\xe9cessaires au d\xe9p\xf4t, au contr\xf4le, \xe0 l'affichage, \xe0 la mod\xe9ration et au signalement des avis sont d\xe9crits dans la Politique de confidentialit\xe9 Croki.","Croki limite l'acc\xe8s aux informations non publiques li\xe9es aux avis aux personnes et prestataires qui en ont besoin pour les finalit\xe9s correspondantes.","Les Professionnels n'ont pas acc\xe8s aux informations priv\xe9es d'un Client qui ne sont pas n\xe9cessaires au fonctionnement normal des avis ou \xe0 la relation contractuelle concern\xe9e."]},{heading:"34. \xc9volution de la politique",paragraphs:["Croki peut faire \xe9voluer le fonctionnement de son syst\xe8me d'avis.","Toute \xe9volution modifiant de mani\xe8re substantielle les conditions de d\xe9p\xf4t, le contr\xf4le, le classement, la possibilit\xe9 de modification, les contreparties, la mod\xe9ration ou les dur\xe9es de publication et de conservation doit \xeatre refl\xe9t\xe9e dans la pr\xe9sente politique.","Croki ne doit pas maintenir une description publique mat\xe9riellement diff\xe9rente du fonctionnement r\xe9el du Service.","La version publi\xe9e indique sa date ou sa version d'entr\xe9e en vigueur."]},{heading:"35. Contact",paragraphs:[`\xc9diteur et gestionnaire des avis : ${t.LEGAL_OPERATOR_NAME}.`,`Service : ${t.LEGAL_TRADE_NAME}.`,`Adresse : ${t.LEGAL_SLOT.registeredOffice}.`,`E-mail : ${t.LEGAL_SLOT.email}.`,`T\xe9l\xe9phone : ${t.LEGAL_SLOT.phone}.`]}]})},1533,[1630,1228]);